def solve(rows):
    filtered_rows = []
    for i, row in enumerate(rows):
        if i % 3 != 1 or i == len(rows) - 1:
            filtered_rows.append(row)

    if not filtered_rows:
        return []

    rotated_rows = filtered_rows[1:] + [filtered_rows[0]]

    last_ok_values = {}
    for row in rotated_rows:
        parts = row.split('|')
        if len(parts) == 3:
            key, value_str, status = parts
            if status == 'OK':
                try:
                    value = int(value_str)
                    last_ok_values[key] = value
                except ValueError:
                    pass

    result = []
    for key, value in last_ok_values.items():
        result.append([key, value])

    result.sort()
    return result

