def solve(rows):
    """Solves the puzzle according to the given rules.

    Args:
        rows: A list of strings representing log rows.

    Returns:
        A sorted list of [key, value] pairs, where value is an integer.
    """

    # Audit filter
    filtered_rows = []
    for i, row in enumerate(rows):
        if i % 3 != 1 and i != len(rows) - 1:
            continue
        filtered_rows.append(row)

    # Rotate rows
    rotated_rows = []
    for row in filtered_rows:
        parts = row.split('|')
        if len(parts) == 3:
            key = parts[0]
            integer_part = parts[1]
            status = parts[2]

            if status == "OK":
                try:
                    value = int(integer_part)
                    if value <= 0:
                        value = 0
                except ValueError:
                    value = 0
                rotated_rows.append([key, value])
            elif status == "VOID":
                pass # Ignore VOID
        else:
            pass # ignore rows that don't fit format

    # Rotate the rows left by 1 position modulo the retained length
    if len(rotated_rows) > 0:
        rotated_rows = rotated_rows[-1:] + rotated_rows[:-1] # Rotate

    # Parse log rows and extract [key, value] pairs
    result = []
    for row in rotated_rows:
        if len(row) == 2:
            result.append(row)

    # Sort the result
    result.sort()
    return result

